const labels={Owner:'Owner',Finance:'Keuangan',Global:'Umum','Global & Laundry':'Umum & Laundry',Cash:'Tunai',Draft:'Draf',Direversal:'Dikoreksi',Open:'Terbuka',Review:'Dalam pemeriksaan',Closed:'Ditutup',Investigating:'Sedang ditelusuri',Resolved:'Selesai',Dismissed:'Ditutup dengan alasan',manual:'Pencatatan keuangan',portal:'Meja laundry',laundry:'Laundry',hunian:'Hunian',settlement:'Setoran',operating:'Operasional',investing:'Investasi',financing:'Pendanaan',internal:'Pemindahan uang',opening:'Saldo awal',asset:'Aset',contraAsset:'Pengurang aset',liability:'Kewajiban',equity:'Modal',draw:'Pengambilan pemilik',revenue:'Pendapatan',contraRevenue:'Pengurang pendapatan',cogs:'Biaya langsung',expense:'Biaya operasional',otherRevenue:'Pendapatan lainnya',otherExpense:'Biaya lainnya',tax:'Pajak','Asia/Jakarta':'WIB','Asia/Makassar':'WITA','Asia/Jayapura':'WIT','SHIFT SUBMITTED':'Laporan pergantian petugas diajukan','SHIFT REVIEWED':'Laporan pergantian petugas diperiksa','PENDING REVIEW':'Menunggu pemeriksaan','EXCEPTION OPEN':'Masih ada kendala','INT: identifikasi & karantina':'Pemilik barang belum diketahui','Pembayaran tanpa settlement':'Pembayaran belum memiliki setoran'};
function label(value){return labels[value]||String(value??'');}
function opaque(value){return /^(?:[a-f0-9]{8}-[a-f0-9-]{27,}|(?:TRX|REV|ATT|PER|BANK|BUD|AUTO|CASH|SNAP)-\S+|(?:portal|manual|system|sb):\S+|system-(?:draft-generator|daily-draft)|m[a-z0-9]{10,})$/i.test(String(value||''));}
